CREATE COLUMN TABLE "TEST_AP"."AOB1" ("AlertCode" INTEGER CS_INT NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '12' NOT NULL , "ObjCode" NVARCHAR(50) NOT NULL , "ObjName" NVARCHAR(155), "SendIntrnl" NVARCHAR(1) DEFAULT 'N', "Confirmed1" NVARCHAR(1) DEFAULT 'N', "ConfDate1" LONGDATE CS_LONGDATE, "ConfTime1" SMALLINT CS_INT, "SendEMail" NVARCHAR(1) DEFAULT 'N', "E_Mail" NVARCHAR(100), "Confirmed2" NVARCHAR(1) DEFAULT 'N', "ConfDate2" LONGDATE CS_LONGDATE, "ConfTime2" SMALLINT CS_INT, "SendSMS" NVARCHAR(1) DEFAULT 'N', "PortNum" NVARCHAR(50), "Confirmed3" NVARCHAR(1) DEFAULT 'N', "ConfDate3" LONGDATE CS_LONGDATE, "ConfTime3" SMALLINT CS_INT, "SendFax" NVARCHAR(1) DEFAULT 'N', "Fax" NVARCHAR(20), "Confirmed4" NVARCHAR(1) DEFAULT 'N', "ConfDate4" LONGDATE CS_LONGDATE, "ConfTime4" SMALLINT CS_INT, PRIMARY KEY ("AlertCode", "ObjType", "ObjCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "AOB1_SEND_EM" ON "TEST_AP"."AOB1" ( "SendEMail" ASC );
CREATE INDEX "AOB1_CONFIRMED2" ON "TEST_AP"."AOB1" ( "Confirmed2" ASC )